# Build output positions based on the "opposite direction" rule
N = 9
BLOCK = (3, 3)
BLOCK_MAIN = 0  # main-diag diff
BLOCK_ANTI = 7  # anti-diag sum

def get_target_input_direction(r_in, c_in):
    """What direction is the input value relative to the block?"""
    center = (BLOCK[0] + 0.5, BLOCK[1] + 0.5)
    rel_r = r_in - center[0]
    rel_c = c_in - center[1]

    # Get quadrant relative to block
    if rel_r < 0 and rel_c < 0:  # TL
        return "TL"
    elif rel_r > 0 and rel_c > 0:  # BR
        return "BR"
    elif rel_r < 0 and rel_c > 0:  # TR
        return "TR"
    elif rel_r > 0 and rel_c < 0:  # BL
        return "BL"
    else:
        return "CENTER"

def get_target_diagonal_type(input_dir):
    """Given input direction, determine target diagonal type"""
    if input_dir in ["TL", "BR"]:
        return "anti"
    else:  # TR, BL
        return "main"

def get_opposite_side(input_dir, diagonal_type):
    """Given input direction and diagonal type, return the side of the target diagonal"""
    if diagonal_type == "anti":  # r+c = BLOCK_ANTI
        if input_dir == "TL":
            return "TR"  # TL input → TR side of anti-diag
        elif input_dir == "BR":
            return "BL"  # BR input → BL side of anti-diag
    else:  # diagonal_type == "main", r-c = BLOCK_MAIN
        if input_dir == "TL":
            return "main_BR"  # TL input → BR side (but wait, r=c means TR=BR)
        elif input_dir == "BL":
            return "main_TL"  # BL input → TL side
    return None

