def add_value_on_diagonal(val, diagonal_type, target_dir):
    """Add value val to grid at all positions on target diagonal, going out from block in target_dir"""
    center = (BLOCK[0] + 0.5, BLOCK[1] + 0.5)
    diag_const = BLOCK_MAIN if diagonal_type == "main" else BLOCK_ANTI

    if diagonal_type == "main":  # r-c = BLOCK_MAIN = 0
        if target_dir == "TL":  # r < 3.5, c < 3.5 (but r=c, so just r < 3.5)
            for r in range(N):
                c = r  # main-diag r-c=0
                if r < center[0] - 0.5:  # r < 3.5 → r ≤ 3
                    result = (r, c)
                    # Don't overlap with 2×2 block
                    if not (3 <= r < 5 and 3 <= c < 5):
                        output[result].append(val)
        elif target_dir == "BR":  # r > 3.5 (since r=c, also c > 3.5)
            for r in range(N):
                c = r  # main-diag r-c=0
                if r > center[0] + 0.5:  # r > 3.5 → r ≥ 4
                    result = (r, c)
                    if not (3 <= r < 5 and 3 <= c < 5):
                        output[result].append(val)
        elif target_dir == "main_BR_actual":  # BR meaning r > center, c > center (which is same as r > center since r=c)
            for r in range(N):
                c = r
                if r > center[0]:  # r > 3.5
                    result = (r, c)
                    if not (3 <= r < 5 and 3 <= c < 5):
                        output[result].append(val)

    elif diagonal_type == "anti":  # r+c = BLOCK_ANTI = 7
        if target_dir == "TR":  # r < 3.5, c > 3.5
            for r in range(N):
                c = diag_const - r
                if r < center[0] and c > center[1]:
                    result = (r, c)
                    if not (3 <= r < 5 and 3 <= c < 5):
                        output[result].append(val)
        elif target_dir == "BL":  # r > 3.5, c < 3.5
            for r in range(N):
                c = diag_const - r
                if r > center[0] and c < center[1]:
                    result = (r, c)
                    if not (3 <= r < 5 and 3 <= c < 5):
                        output[result].append(val)

