# Function to get output positions for a value
output = {}

def get_target_direction(r_in, c_in, block):
    """Get input direction relative to block center, return target diagonal and side"""
    center = (block[0] + 0.5, block[1] + 0.5)
    rel_r = r_in - center[0]
    rel_c = c_in - center[1]

    if rel_r < 0 and rel_c < 0:  # TL
        return "anti", "TR", (block[0] + block[1] + 1), 7  # anti-diag constant
    elif rel_r > 0 and rel_c > 0:  # BR
        return "anti", "BL", (block[0] + block[1] + 1), 7
    elif rel_r < 0 and rel_c > 0:  # TR
        return "main", "BR", (block[0] - block[1]), 0
    elif rel_r > 0 and rel_c < 0:  # BL
        return "main", "TL", (block[0] - block[1]), 0
    return None, None, None, None

def compute_output_for_value(val, r_in, c_in):
    """Compute output positions for a single value"""
    positions = []
    for block in INPUT_2S:
        diag_type, target_dir, diag_const, center_r = get_target_direction(r_in, c_in, block)
        if diag_type is None:
            continue

        # Main-diag: r-c = diag_const
        if diag_type == "main":
            if target_dir == "TL":  # r < center_r
                for r in range(N):
                    if r < center_r - 0.5 and r - c_in > -100:  # r-c check
                        c = r - diag_const
                        if 0 <= c < N:
                            positions.append((r, c))
            elif target_dir == "BR":  # r > center_r
                for r in range(N):
                    if r > center_r + 0.5:
                        c = r - diag_const
                        if 0 <= c < N:
                            positions.append((r, c))
        else:  # anti-diag: r+c = diag_const
            if target_dir == "TR":  # r < center_r and c > center_c
                for r in range(N):
                    c = diag_const - r
                    if r < center_r - 0.5 and c > center_r - 0.5:
                        if 0 <= c < N:
                            positions.append((r, c))
            elif target_dir == "BL":  # r > center_r and c < center_c
                for r in range(N):
                    c = diag_const - r
                    if r > center_r + 0.5 and c < center_r - 0.5:
                        if 0 <= c < N:
                            positions.append((r, c))

    return positions

