# Let me simplify and test directly with hardcoded rules
def transform_simple(grid):
    N = len(grid)
    output = [[0]*N for _ in range(N)]

    for r in range(N):
        for c in range(N):
            if grid[r][c] != 2:
                val = grid[r][c]
                # Find nearest 2x2 block
                blocks = []
                for br in range(N-1):
                    for bc in range(N-1):
                        if grid[br][bc] == 2 and grid[br][bc+1] == 2 and grid[br+1][bc] == 2 and grid[br+1][bc+1] == 2:
                            blocks.append((br, bc))

                # Find closest block
                min_dist = float('inf')
                closest = None
                for br, bc in blocks:
                    # Distance from nearest block cell
                    dist = min(abs(r - br) + abs(c - bc), abs(r - (br+1)) + abs(c - bc), abs(r - br) + abs(c - (bc+1)), abs(r - (br+1)) + abs(c - (bc+1)))
                    if dist < min_dist:
                        min_dist = dist
                        closest = (br, bc)

                if closest:
                    br, bc = closest
                    center_r, center_c = br + 0.5, bc + 0.5

                    if r < center_r and c < center_c:
                        # ABOVE-LEFT → anti-diagonal targeting (0, N-2)
                        const = r + c
                        # Fill along anti-diagonal
                        for nr in range(N):
                            nc = const - nr
                            if 0 <= nc < N:
                                # Check if further from block than input
                                if (br+0.5, bc+0.5) is not None:
                                    pass
                                output[nr][nc] = val
                    elif r < center_r and c > center_c:
                        # ABOVE-RIGHT → main-diagonal targeting (N-1, N-1)
                        const = r - c
                        for nr in range(N):
                            nc = nr - const
                            if 0 <= nc < N:
                                output[nr][nc] = val
                    elif r > center_r and c < center_c:
                        # BELOW-LEFT → main-diagonal targeting (0, 0)
                        const = r - c
                        for nr in range(N):
                            nc = nr - const
                            if 0 <= nc < N:
                                output[nr][nc] = val
                    elif r > center_r and c > center_c:
                        # BELOW-RIGHT → anti-diagonal targeting (N-2, 0)
                        const = r + c
                        for nr in range(N):
                            nc = const - nr
                            if 0 <= nc < N:
                                output[nr][nc] = val

    return output

