def transform_v2(grid):
    N = len(grid)
    output = [[0]*N for _ in range(N)]
    visited = [[False]*N for _ in range(N)]

    # Find all 2x2 blocks
    blocks = []
    for r in range(N-1):
        for c in range(N-1):
            if grid[r][c] == 2 and grid[r][c+1] == 2 and grid[r+1][c] == 2 and grid[r+1][c+1] == 2:
                blocks.append((r, c))

    # Get block centers
    block_centers = [(br + 0.5, bc + 0.5) for br, bc in blocks]

    for r in range(N):
        for c in range(N):
            if grid[r][c] == 2:
                continue

            val = grid[r][c]

            # Find closest block
            min_dist = float('inf')
            closest_center = None
            for center in block_centers:
                dist = abs(r - center[0]) + abs(c - center[1])
                if dist < min_dist:
                    min_dist = dist
                    closest_center = center

            if closest_center:
                center_r, center_c = closest_center

                # Determine quadrant
                if r < center_r - 0.5 and c < center_c - 0.5:
                    # ABOVE-LEFT → anti-diagonal (r+c=const), extend toward TOP-RIGHT
                    # Calculate target r+c: for 9x9 Demo 0, it's r+c=7
                    # r+c=7 is the middle anti-diagonal, touching the block
                    # For 8x8, it should be r+c=6 or 7?
                    # Let's use: r+c = block_center_row + block_center_col
                    const = int(center_r + center_c)

                    # Find all positions on this anti-diagonal
                    positions = []
                    for nr in range(N):
                        nc = const - nr
                        if 0 <= nc < N:
                            positions.append((nr, nc))

                    # Sort by distance from block: want positions further from block than input
                    # Sort by r (for anti-diag, lower r = higher c = toward TOP-RIGHT)
                    positions.sort(key=lambda p: p[0], reverse=True)

                    # Mark starting position from closest cell in quadrant
                    start_idx = 0
                    for idx, (nr, nc) in enumerate(positions):
                        if abs(nr - center_r) + abs(nc - center_c) >= min_dist:
                            start_idx = idx
                            break

                    # Fill from start towards corner (lower r for TOP-RIGHT)
                    for idx in range(start_idx, len(positions)):
                        nr, nc = positions[idx]
                        if not visited[nr][nc]:
                            visited[nr][nc] = True
                            output[nr][nc] = val

                elif r < center_r - 0.5 and c > center_c + 0.5:
                    # ABOVE-RIGHT → main-diagonal (r-c=0), extend toward BOTTOM-RIGHT
                    const = 0  # r-c=0 passes through (0,0) to (N-1,N-1)

                    positions = [(nr, nr) for nr in range(N)]
                    positions.sort(key=lambda p: p[0])  # lower to higher r = toward bottom-right

                    for nr, nc in positions:
                        if not visited[nr][nc]:
                            # Check if further from block than input
                            dist_from = abs(nr - center_r) + abs(nc - center_c)
                            if dist_from >= min_dist:
                                visited[nr][nc] = True
                                output[nr][nc] = val

                elif r > center_r + 0.5 and c < center_c - 0.5:
                    # BELOW-LEFT → main-diagonal (r-c=0), extend toward TOP-LEFT
                    const = 0

                    positions = [(nr, nr) for nr in range(N)]
                    positions.sort(key=lambda p: p[0], reverse=True)  # highest r first = toward top-left

                    for nr, nc in positions:
                        if not visited[nr][nc]:
                            dist_from = abs(nr - center_r) + abs(nc - center_c)
                            if dist_from >= min_dist:
                                visited[nr][nc] = True
                                output[nr][nc] = val

                elif r > center_r + 0.5 and c > center_c + 0.5:
                    # BELOW-RIGHT → anti-diagonal (r+c=const), extend toward BOTTOM-LEFT
                    const = int(center_r + center_c)

                    positions = []
                    for nr in range(N):
                        nc = const - nr
                        if 0 <= nc < N:
                            positions.append((nr, nc))

                    # Sort by r ascending = toward bottom-left (higher r, lower c)
                    positions.sort(key=lambda p: p[0])

                    for nr, nc in positions:
                        if not visited[nr][nc]:
                            dist_from = abs(nr - center_r) + abs(nc - center_c)
                            if dist_from >= min_dist:
                                visited[nr][nc] = True
                                output[nr][nc] = val

    return output

